    'ui.rewrite_suffix_mac' => ['zh' => '会加在苹果链接后面。', 'en' => 'is appended to Apple-style links.', 'de' => 'wird an Apple-Links angehängt.', 'es' => 'se añade a los enlaces estilo Apple.', 'fr' => 's’ajoute aux liens style Apple.', 'ko' => '애플 링크 뒤에 붙습니다.', 'pt' => 'acrescenta-se às ligações estilo Apple.', 'ja' => 'アップル風リンクの後ろに付きます。'],
    'ui.rewrite_no_html' => ['zh' => '本站路由一般不带 <code>.html</code>。', 'en' => 'This-site routes usually have no <code>.html</code>.', 'de' => 'Eigene Routen haben meist kein <code>.html</code>.', 'es' => 'Las rutas de este sitio suelen ir sin <code>.html</code>.', 'fr' => 'Les routes du site n’ont souvent pas de <code>.html</code>.', 'ko' => '이 사이트 라우트는 보통 <code>.html</code> 이 없습니다.', 'pt' => 'As rotas deste site costumam ir sem <code>.html</code>.', 'ja' => '本サイト経路はだいたい <code>.html</code> なし。'],
    'ui.rewrite_how_body' => ['zh' => '地址写在 Laravel 路由里，不是苹果那种伪静态规则文件。没有真实文件的请求交给 <code>public/index.php</code> 即可。两种链接写法用同一段 Nginx / Apache，不必按每种页面再写 location。', 'en' => 'URLs live in Laravel routes, not an Apple rewrite file. Requests without a real file go to <code>public/index.php</code>. Both link styles share one Nginx / Apache block; you do not write a location per page.', 'de' => 'Adressen stehen in Laravel-Routen, nicht in einer Apple-Rewrite-Datei. Anfragen ohne echte Datei gehen an <code>public/index.php</code>. Beide Linkstile teilen einen Nginx-/Apache-Block.', 'es' => 'Las direcciones viven en rutas Laravel, no en un archivo Apple. Lo que no es archivo real va a <code>public/index.php</code>. Ambos estilos comparten un bloque Nginx / Apache.', 'fr' => 'Les adresses sont dans les routes Laravel, pas un fichier Apple. Sans fichier réel, ça va à <code>public/index.php</code>. Les deux styles partagent un bloc Nginx / Apache.', 'ko' => '주소는 Laravel 라우트에 있고 애플 규칙 파일이 아닙니다. 실제 파일이 없으면 <code>public/index.php</code> 로 갑니다. 두 링크 쓰기는 Nginx / Apache 한 덩어리를 같이 씁니다.', 'pt' => 'Os endereços estão nas rotas Laravel, não num ficheiro Apple. Sem ficheiro real vai a <code>public/index.php</code>. Os dois estilos partilham um bloco Nginx / Apache.', 'ja' => '住所は Laravel 経路にあり、アップルの規則ファイルではありません。実ファイルがなければ <code>public/index.php</code> へ。二種のリンクは同じ Nginx / Apache で足ります。'],
    'ui.rewrite_faq_title' => ['zh' => '上线打开是目录或 404', 'en' => 'Live site shows a directory or 404', 'de' => 'Live öffnet ein Verzeichnis oder 404', 'es' => 'En línea sale un directorio o 404', 'fr' => 'En ligne on voit un dossier ou 404', 'ko' => '올린 뒤 디렉터리나 404 가 나옴', 'pt' => 'Em produção aparece uma pasta ou 404', 'ja' => '公開するとディレクトリや 404 になる'],
    'ui.rewrite_faq_body' => ['zh' => '网站根必须指到项目的 <code>public</code>，不要指到项目根。本页下面的 Nginx / Apache 就是干这个的。', 'en' => 'The site root must point at the project <code>public</code> folder, not the project root. The Nginx / Apache below does that.', 'de' => 'Die Site-Wurzel muss auf <code>public</code> zeigen, nicht auf die Projektwurzel. Nginx / Apache unten erledigt das.', 'es' => 'La raíz del sitio debe apuntar a <code>public</code>, no a la raíz del proyecto. El Nginx / Apache de abajo lo hace.', 'fr' => 'La racine du site doit viser <code>public</code>, pas la racine du projet. Le Nginx / Apache ci-dessous le fait.', 'ko' => '사이트 루트는 프로젝트 <code>public</code> 이어야 하며 프로젝트 루트가 아닙니다. 아래 Nginx / Apache 가 그 일입니다.', 'pt' => 'A raiz do site deve apontar a <code>public</code>, não à raiz do projecto. O Nginx / Apache abaixo faz isso.', 'ja' => 'サイトルートはプロジェクトの <code>public</code> で、プロジェクト根ではありません。下の Nginx / Apache がそれをします。'],
    'ui.rewrite_lead_before' => ['zh' => '本机 <code>php artisan serve</code> 只适合试用，不用配下面规则。正式站点要把网站根指到项目的 <code>public</code>，不要指到项目根。影片链接怎么写在', 'en' => 'Local <code>php artisan serve</code> is for trying only; skip the rules below. A live site must point the web root at project <code>public</code>, not the project root. Video URL style is in', 'de' => 'Lokales <code>php artisan serve</code> nur zum Ausprobieren; Regeln unten weglassen. Live muss die Wurzel auf <code>public</code> zeigen. Die Video-URL-Schreibweise steht unter', 'es' => '<code>php artisan serve</code> local solo para probar; omita las reglas. En línea la raíz debe ser <code>public</code>. Cómo se escriben los vídeos está en', 'fr' => '<code>php artisan serve</code> local est un essai ; ignorez les règles. En ligne la racine doit être <code>public</code>. L’écriture des URL vidéo est dans', 'ko' => '로컬 <code>php artisan serve</code> 는 시험용이며 아래 규칙은 필요 없습니다. 실서비스 루트는 <code>public</code> 이어야 합니다. 영상 링크 쓰기는', 'pt' => '<code>php artisan serve</code> local é só para tentar; salte as regras. Em produção a raiz deve ser <code>public</code>. A escrita dos URLs de vídeo está em', 'ja' => '手元の <code>php artisan serve</code> は試用だけ。下の規則は不要。本番のルートは <code>public</code>。動画リンクの書き方は'],
    'ui.rewrite_lead_after' => ['zh' => '：本站路由一般是 <code>/vod/123</code>，苹果风格才是 <code>/index.php/vod/detail/id/123.html</code>。改过之后，外面收藏的旧地址可能打不开。', 'en' => ': this-site routes are usually <code>/vod/123</code>; Apple style is <code>/index.php/vod/detail/id/123.html</code>. After a change, old bookmarks may 404.', 'de' => ': eigene Routen meist <code>/vod/123</code>; Apple-Stil <code>/index.php/vod/detail/id/123.html</code>. Danach können alte Lesezeichen 404 sein.', 'es' => ': las rutas de este sitio suelen ser <code>/vod/123</code>; estilo Apple <code>/index.php/vod/detail/id/123.html</code>. Tras el cambio, los marcadores viejos pueden fallar.', 'fr' => ' : les routes du site sont souvent <code>/vod/123</code> ; style Apple <code>/index.php/vod/detail/id/123.html</code>. Après changement, les anciens favoris peuvent 404.', 'ko' => ': 이 사이트 라우트는 보통 <code>/vod/123</code>, 애플 스타일은 <code>/index.php/vod/detail/id/123.html</code>. 바꾼 뒤 바깥 북마크는 열리지 않을 수 있습니다.', 'pt' => ': as rotas deste site costumam ser <code>/vod/123</code>; estilo Apple <code>/index.php/vod/detail/id/123.html</code>. Depois da mudança, marcadores antigos podem falhar.', 'ja' => '：本サイト経路はだいたい <code>/vod/123</code>。アップル風は <code>/index.php/vod/detail/id/123.html</code>。変えたあと外の旧住所は開けないことがあります。'],
    'ui.rewrite_nginx_hint' => ['zh' => '网站根必须是 <code>public</code>。PHP 那一行按机器改。苹果链接也进 <code>index.php</code>，不必再单独写一段 location。', 'en' => 'The web root must be <code>public</code>. Change the PHP line for your machine. Apple-style links also hit <code>index.php</code>; no extra location.', 'de' => 'Wurzel muss <code>public</code> sein. PHP-Zeile je Maschine. Apple-Links gehen auch an <code>index.php</code>.', 'es' => 'La raíz debe ser <code>public</code>. Cambie la línea PHP. Los enlaces Apple también van a <code>index.php</code>.', 'fr' => 'La racine doit être <code>public</code>. Adaptez la ligne PHP. Les liens Apple vont aussi à <code>index.php</code>.', 'ko' => '루트는 <code>public</code>. PHP 줄은 기계에 맞게. 애플 링크도 <code>index.php</code> 로 가며 location 을 더 쓰지 않습니다.', 'pt' => 'A raiz deve ser <code>public</code>. Ajuste a linha PHP. Ligações Apple também vão a <code>index.php</code>.', 'ja' => 'ルートは <code>public</code>。PHP 行は機械に合わせる。アップル風も <code>index.php</code> へ。別 location は不要。'],
    'ui.rewrite_apache_hint' => ['zh' => '仓库 <code>public/.htaccess</code> 已有一份。虚拟主机要允许 <code>AllowOverride All</code>。', 'en' => 'The repo already has <code>public/.htaccess</code>. The vhost must allow <code>AllowOverride All</code>.', 'de' => 'Im Repo liegt <code>public/.htaccess</code>. Der VHost braucht <code>AllowOverride All</code>.', 'es' => 'El repo ya tiene <code>public/.htaccess</code>. El vhost debe permitir <code>AllowOverride All</code>.', 'fr' => 'Le dépôt a déjà <code>public/.htaccess</code>. Le vhost doit autoriser <code>AllowOverride All</code>.', 'ko' => '저장소에 이미 <code>public/.htaccess</code> 가 있습니다. 가상호스트는 <code>AllowOverride All</code> 이어야 합니다.', 'pt' => 'O repositório já tem <code>public/.htaccess</code>. O vhost deve permitir <code>AllowOverride All</code>.', 'ja' => '倉庫に <code>public/.htaccess</code> があります。仮想ホストは <code>AllowOverride All</code>。'],
    'ui.rewrite_no_mac_alias' => ['zh' => '最近更新、演员库、专题列表、播放器内嵌仍走本站路径，没有苹果别名。', 'en' => 'Latest, actors, topics, and the player embed still use this-site paths. No Apple aliases.', 'de' => 'Zuletzt, Schauspieler, Themen und Player-Embed bleiben eigene Pfade. Keine Apple-Aliase.', 'es' => 'Recientes, actores, temas y el embebido del reproductor siguen rutas de este sitio. Sin alias Apple.', 'fr' => 'Récents, acteurs, sujets et l’embed lecteur restent des chemins du site. Pas d’alias Apple.', 'ko' => '최근·배우·특집·플레이어 삽입은 이 사이트 경로입니다. 애플 별명 없음.', 'pt' => 'Recentes, actores, tópicos e o embed do leitor ficam nestas rotas. Sem alias Apple.', 'ja' => '最近・俳優・特集・プレーヤー埋め込みは本サイト経路。アップル別名なし。'],
